#!/usr/bin/env node
/**
 * Postbuild patch: add lang="en" to Next.js's internal error shell.
 *
 * Why: `.next/server/app/_global-error.html` is generated by Next itself
 * (not from our global-error.tsx, which only hydrates client-side after a
 * real crash). The generated `<html id="__next_error__">` has no `lang`
 * attribute, which fails Lighthouse's `html-has-lang` audit (weight 7) and,
 * more importantly, deprives screen-reader users of the correct document
 * language on the deployed crash page.
 *
 * Idempotent: skips if a lang attribute is already present.
 * Self-verifying: if Next changes the markup so the patch no longer
 * matches, the script exits non-zero and fails the build loudly instead of
 * silently regressing.
 */
import { readFileSync, writeFileSync } from "node:fs";

const FILE = new URL("../.next/server/app/_global-error.html", import.meta.url);

let html;
try {
  html = readFileSync(FILE, "utf8");
} catch {
  console.error("patch-error-html: .next/server/app/_global-error.html not found — was `next build` run?");
  process.exit(1);
}

if (/<html[^>]*\slang=/.test(html)) {
  console.log("patch-error-html: lang already present — nothing to do");
  process.exit(0);
}

const patched = html.replace(/<html\b([^>]*)>/, (m, attrs) =>
  `<html${attrs} lang="en">`
);

if (patched === html) {
  console.error("patch-error-html: could not find an <html> tag to patch — Next.js output format may have changed");
  process.exit(1);
}

writeFileSync(FILE, patched);
console.log("patch-error-html: added lang=\"en\" to _global-error.html");
